#!/usr/bin/env python3
"""Remove duplicate lines while preserving the order of first occurrence."""

import argparse
import sys


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Remove duplicate lines from a file, keeping the first occurrence of each line."
    )
    parser.add_argument(
        "input",
        nargs="?",
        help="input file (if omitted, reads from stdin)",
    )
    parser.add_argument(
        "-o", "--output",
        help="output file (if omitted, writes to stdout)",
    )
    parser.add_argument(
        "--ignore-case",
        action="store_true",
        help="treat lines that differ only by letter case as duplicates",
    )
    args = parser.parse_args()

    if args.input:
        infile = open(args.input, "r", encoding="utf-8")
    else:
        infile = sys.stdin

    if args.output:
        outfile = open(args.output, "w", encoding="utf-8")
    else:
        outfile = sys.stdout

    seen = set()
    try:
        for line in infile:
            key = line.rstrip("\r\n")
            if args.ignore_case:
                key = key.casefold()
            if key not in seen:
                seen.add(key)
                outfile.write(line)
    finally:
        if infile is not sys.stdin:
            infile.close()
        if outfile is not sys.stdout:
            outfile.close()


if __name__ == "__main__":
    main()

